      'fonts.jszip_unavailable': '\u0411\u0456\u0431\u043B\u0456\u043E\u0442\u0435\u043A\u0430 JSZip \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u2014 \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C \u0440\u043E\u0437\u043F\u0430\u043A\u043E\u0432\u0430\u043D\u0443 \u043F\u0430\u043F\u043A\u0443 \u0437\u0430\u043C\u0456\u0441\u0442\u044C \u0430\u0440\u0445\u0456\u0432\u0443.',
      'fonts.no_regular': '\u0423 \u043F\u0430\u043F\u0446\u0456 \u043D\u0435 \u0437\u043D\u0430\u0439\u0434\u0435\u043D\u043E \u0444\u0430\u0439\u043B \u043D\u0430\u0447\u0435\u0440\u0442\u0430\u043D\u043D\u044F Regular \u2014 \u043D\u0430\u0437\u0432\u0456\u0442\u044C \u0439\u043E\u0433\u043E \u0442\u0430\u043A, \u0449\u043E\u0431 \u0456\u043C\u2019\u044F \u043D\u0435 \u043C\u0456\u0441\u0442\u0438\u043B\u043E "bold" \u0447\u0438 "italic" (\u043D\u0430\u043F\u0440\u0438\u043A\u043B\u0430\u0434, "FontName-Regular.ttf").',
      'fonts.ignored_extra': ' \u2014 \u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043E {count} \u0437\u0430\u0439\u0432\u0438\u0445 \u0444\u0430\u0439\u043B(\u0456\u0432) (\u0441\u043B\u043E\u0442 \u0441\u0442\u0438\u043B\u044E \u0432\u0436\u0435 \u0437\u0430\u0439\u043D\u044F\u0442\u043E): {names}',
